codeExamples.code:
const p1 = new Promise((res) => setTimeout(() => res('P1 Success'), 3000));
const p2 = new Promise((_, rej) => setTimeout(() => rej('P2 Failed'), 1000));
const p3 = new Promise((res) => setTimeout(() => res('P3 Success'), 2000));

// Promise.all -> Fails fast at 1000ms with 'P2 Failed'
Promise.all([p1, p3]).then(console.log); // ['P1 Success', 'P3 Success']

// Promise.allSettled -> Drains all 3 promises
Promise.allSettled([p1, p2, p3]).then(console.log);

// Promise.race -> Wins at 1000ms with rejection 'P2 Failed'
Promise.race([p1, p2, p3]).catch(console.error);

// Promise.any -> First fulfilled at 2000ms is 'P3 Success'
Promise.any([p1, p2, p3]).then(console.log);

